// Refreshes the bundled fallback list for the dice widget's "The Useless Web" source.
//   npm run update:uselessweb
// Fetches the live list with the same extraction code the widget uses and rewrites
// providers/random-sites/theuselessweb-snapshot.js. Review the diff, then commit.
import { writeFileSync } from "node:fs";
import { fetchSites } from "../providers/random-sites/theuselessweb.js";

const { version, sites } = await fetchSites();
const out = `// @ts-check
// GENERATED by dev/update-uselessweb.mjs — do not edit by hand.
// Fallback copy of The Useless Web's site list (https://theuselessweb.com/, curated by Tim Holman),
// used when the live list can't be fetched (no host access, offline, format change).

export const SNAPSHOT = {
  version: ${JSON.stringify(version)},
  takenAt: ${JSON.stringify(new Date().toLocaleDateString("sv"))},
  sites: [
${sites.map(s => `    ${JSON.stringify(s)},`).join("\n")}
  ],
};
`;
writeFileSync("providers/random-sites/theuselessweb-snapshot.js", out);
console.log(`snapshot: ${sites.length} sites (list version "${version}")`);
